// v28.xx (cw-cx-capturechrome): recorded labels cannot show through the title or wake prompt; the arcade keeps its own page layout.
st.textContent+='body #attract[data-capture-playback="1"]{background:var(--ui-void)}'+
  'body #attract[data-capture-playback="1"] .attname{left:50%;right:auto;top:5%;width:max-content;max-width:90vw;min-width:6em;box-sizing:border-box;transform:translateX(-50%);padding:.28em .7em;background:var(--ui-void);border:1px solid var(--ui-line-hi);border-radius:var(--rad);font-size:clamp(56px,5.185185vh,224px);text-shadow:none;opacity:1}'+
  'body #attract[data-capture-playback="1"] .attpress{left:50%;right:auto;bottom:12%;width:max-content;max-width:90vw;box-sizing:border-box;transform:translateX(-50%);padding:.25em .75em;background:var(--ui-void);border:1px solid var(--ui-line-hi);border-radius:var(--rad);font-size:clamp(32px,2.962963vh,128px);text-shadow:none}';
document.head.appendChild(st);
var d=document.createElement('div'); d.id='attract';

var arcade=!!(typeof ARCADE==='object'&&ARCADE&&ARCADE.on);
d.setAttribute('data-capture-playback',arcade?'0':'1'); // v28.xx (cw-cx-capturechrome): only the recorded-footage view gets these backplates.
var ap=d.querySelector('.attpress'); if(ap&&!arcade) ap.textContent=padOn()?'press any button':'press any key';

// v28.xx (cw-cx-capturechrome): the elapsed badge keeps its 20px reading size at 1080p and 40px at 4K.
REC.mark.style.cssText='position:fixed;left:clamp(24px,2.222222vh,96px);top:clamp(24px,2.222222vh,96px);z-index:9001;display:none;padding:.4em .8em;border:1px solid var(--ui-line-hi);border-radius:var(--rad);background:var(--ui-panel);'+
  'color:#ff5a4a;font:700 clamp(20px,1.851852vh,80px) var(--f-cond);letter-spacing:var(--track);pointer-events:none';

check:
{v:'VER',what:'recorded-footage titles have opaque backplates, the wake prompt stays above the lower footage and the elapsed badge scales with resolution',
 run:function(){
   var bad=[], d, name, prompt, mark, cs, oldState=state, oldArc=ARCADE.on, oldGate=FSG.open, last=ATT.last, shown=REC.mark&&REC.mark.style.display;
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __hubEnter(); __topClear(); ARCADE.on=false; FSG.open=false;
     if(document.activeElement&&document.activeElement.blur) document.activeElement.blur();
     ATT.last=Date.now()-31000; attShow('data:video/mp4;base64,AAAA'); d=attEl();
     if(d.getAttribute('data-capture-playback')!=='1') bad.push('the footage layout was not selected');
     d.style.display='block'; name=d.querySelector('.attname'); prompt=d.querySelector('.attpress');
     cs=getComputedStyle(name);
     if(cs.backgroundImage!=='none'||cs.backgroundColor!=='rgb(11, 12, 13)') bad.push('the title still lets recorded labels through');
     if(parseFloat(cs.fontSize)<55) bad.push('the footage title is below 56px');
     cs=getComputedStyle(prompt);
     if(cs.backgroundImage!=='none'||cs.backgroundColor!=='rgb(11, 12, 13)') bad.push('the wake prompt still has a transparent band');
     if(parseFloat(cs.fontSize)<31) bad.push('the footage wake prompt is below 32px');
     if(prompt.getBoundingClientRect().bottom>innerHeight*.89) bad.push('the wake prompt is too close to the footage edge');
     recMark(true); mark=REC.mark; cs=getComputedStyle(mark);
     if(Math.abs(parseFloat(cs.fontSize)-Math.max(20,innerHeight*20/1080))>0.6) bad.push('the recording badge does not scale to a readable 1080p size');
     if(cs.borderRadius!=='4px') bad.push('the recording badge has a separate pill style');
     attStop(); if(d.hasAttribute('data-capture-playback')) bad.push('the footage layout leaked into the arcade');
     return bad.length?bad.join('; '):null;
   }finally{ attStop(); if(REC.mark) REC.mark.style.display=shown||'none'; state=oldState; ARCADE.on=oldArc; FSG.open=oldGate; ATT.last=last; __topClear(); }
 }},
